L.SET_ID = "Gear Set ID"
L.SHARED = "Shared"
L.SHARED_APPEARANCES_CHECKBOX = "Shared Appearances"
L.SHARED_APPEARANCES_CHECKBOX_TOOLTIP = "Enable this option to see items that share a similar appearance in the tooltip.\n\nNOTE: Items that do not match the armor type are displayed in the list. This is to help you diagnose the Collection progress.\n\nIf you are ever confused by this, as of ATT v1.5.0, you can Right Click the item to open the item and its Shared Appearances into their own standalone Mini List."
L.SHOPPING_OP_MISSING_1 = "The preset is missing a 'Shopping' Operation assignment."
L.SHOPPING_OP_MISSING_2 = "Type '/tsm operations' to create or assign one."
L.SHORTTITLE = "|c" .. _.DefaultColors.ATT .. "ATT|r"
L.SHOW_ALL_LEARNABLE_QUEST_REWARDS_CHECKBOX = "All Learnable Quest Rewards"
L.SHOW_ALL_LEARNABLE_QUEST_REWARDS_CHECKBOX_TOOLTIP = "Disable this option to hide items that are listed as \"Not Available in Personal Loot\" for quests.\n\nThis is useful for tracking items that your class can't use in World Drops, but still marking quests as completed.\n\nSome items can be marked incorrectly: this setting WILL hide items that you can obtain!"
L.SHOW_ALL_SEASONAL = "All Seasonal Events"
L.SHOW_ALL_SEASONAL_TOOLTIP = "Enable this setting to show all seasonal events, instead of only currently active seasonal events.\n\nNOTE: Seasonal Events will automatically be visible as active 7 days in advance."
L.SHOW_BOE_CHECKBOX = "BoE/Warbound Items"
L.SHOW_BOE_CHECKBOX_TOOLTIP = "Enable this setting if you want to show Bind-on-Equip/Account items.\n\nDisabling this setting is useful for when you are trying to finish a Classic Dungeon for a character and don't want to farm specifically for items that can be farmed on alts or on the Auction House.\n\nIE: Don't lose your mind grinding for Pendulum of Doom."
L.SHOW_CHALLENGE_MASTER_CHECKBOX = CHALLENGE_MODE_REALM_BEST
L.SHOW_CHALLENGE_MASTER_CHECKBOX_TOOLTIP = "Enable this setting if you want to show content which requires achieving Realm Best times in Challenge Modes."
L.SHOW_COLLECTED_THINGS_CHECKBOX = "Show Collected Things"
L.SHOW_COLLECTED_THINGS_CHECKBOX_TOOLTIP = "Enable this option to see Things which have already been Collected.\n\nWe recommend you turn this setting off as it will conserve the space in the mini list and allow you to quickly see what you are missing from the zone."
L.SHOW_COLLECTION_PROGRESS_CHECKBOX = "Collection Progress"
L.SHOW_COLLECTION_PROGRESS_CHECKBOX_TOOLTIP = "Enable this option if you want to see your progress towards collecting a Thing or completing a group of Things at the Top Right of its tooltip.\n\nWe recommend that you keep this setting turned on."
L.SHOW_COMPLETED_GROUPS_CHECKBOX = "Show Completed Groups"
L.SHOW_COMPLETED_GROUPS_CHECKBOX_TOOLTIP = "Enable this option if you want to see completed groups as a header with a completion percentage. If a group has nothing relevant for your class, this setting will also make those groups appear in the listing.\n\nWe recommend you turn this setting off as it will conserve the space in the mini list and allow you to quickly see what you are missing from the zone."
L.SHOW_CRAFTED_ITEMS_CHECKBOX = "Show Crafted Items"
L.SHOW_CRAFTED_ITEMS_CHECKBOX_TOOLTIP = "Enable this option if you want to see a list of all of the items that can be crafted by any of your characters for a reagent in its tooltip."
L.SHOW_CURRENCY_CALCULATIONS_CHECKBOX = "Currency calculation"
L.SHOW_CURRENCY_CALCULATIONS_CHECKBOX_TOOLTIP = "Enable this option to show the estimated amount of Items/Currency required to collect Things.\n\nFor Containers which do not reward all of their available content at once, the estimate will thus be lower than actually required."
L.SHOW_ICON_PORTRAIT_CHECKBOX = "Icon Portraits"
L.SHOW_ICON_PORTRAIT_CHECKBOX_TOOLTIP = "Enable this option if you want to see creature icon portraits instead of the default icons for non-quest object types.\n\nIE: When looking at bosses, this option will show the face of the boss instead of the difficulty icon.\n\nDefault: On"
L.SHOW_ICON_PORTRAIT_FOR_QUESTS_CHECKBOX = "For Quests"
L.SHOW_ICON_PORTRAIT_FOR_QUESTS_CHECKBOX_TOOLTIP = "Enable this option if you want to see creature icon portraits instead of the default icons for quest object types.\n\nIE: When looking at quests, this option will show the face of the quest giver instead of the quest type icon.\n\nDefault: On"
L.SHOW_INCOMPLETE_THINGS_CHECKBOX = "Show Repeatable/Trackable Things"
L.SHOW_INCOMPLETE_THINGS_CHECKBOX_TOOLTIP = "Enable this option if you want to see incomplete repeatable content without forcing it to be considered 'collectible'.\n\nNOTE: Non-saved Rare Spawns, Treasures, and Vignettes also appear in the listing with this setting turned on."
L.SHOW_MODELS_CHECKBOX = "Model Preview"
L.SHOW_MODELS_CHECKBOX_TOOLTIP = "Enable this option to show models within a preview instead of the icon on the tooltip.\n\nThis option may assist you in identifying what a Rare Spawn or Vendor looks like. It might be a good idea to keep this turned on for that reason."
L.SHOW_ONLY_NON_TRIVIAL_RECIPES_CHECKBOX = "Only Non-Trivial"
L.SHOW_ONLY_NON_TRIVIAL_RECIPES_CHECKBOX_TOOLTIP = "Enable this option if you only want to see non-trivial recipes in the recipe list."
L.SHOW_PET_BATTLES_CHECKBOX = SHOW_PET_BATTLES_ON_MAP_TEXT
L.SHOW_PET_BATTLES_CHECKBOX_TOOLTIP = "Enable this setting if you want to show content which requires Pet Battles within the game."
L.SHOW_PROFILE_LOADED = "Show which profile loads during login or when switching between profiles"
L.SHOW_PVP_CHECKBOX = PVP_OPTIONS
L.SHOW_PVP_CHECKBOX_TOOLTIP = "Enable this setting if you want to show content which 'may' require Player vs. Player interactions within the game."
L.SHOW_RECIPES_CHECKBOX = "Show Recipes"
L.SHOW_RECIPES_CHECKBOX_TOOLTIP = "Enable this option if you want to see a list of all of the recipes that can be crafted by any of your characters for a reagent in its tooltip."
L.SHOW_REMAINING_CHECKBOX = "Show Remaining Things"
L.SHOW_REMAINING_CHECKBOX_TOOLTIP = "Enable this option if you want to see the number of items remaining instead of the progress over total."
L.SHOW_SKYRIDING_CHECKBOX = ACCESSIBILITY_ADV_FLY_LABEL
L.SHOW_SKYRIDING_CHECKBOX_TOOLTIP = "Enable this setting if you want to show content which requires Skyriding within the game."
L.SKIP_AUTO_REFRESH = "Skip Settings-Toggle Data Refreshes!"
L.SKIP_AUTO_REFRESH_TOOLTIP = "By default (unchecked), any Settings change which may affect visible data will cause an automatic refresh.\n\nBy enabling this option, Settings changes won't take effect until the User performs a Full Refresh by " .. SHIFT_KEY_TEXT .. " clicking on an ATT window."
L.SKIP_CUTSCENES_CHECKBOX = "Automatically Skip Cutscenes"
L.SKIP_CUTSCENES_CHECKBOX_TOOLTIP = "Enable this option if you want ATT to automatically skip all cutscenes on your behalf."
L.SOCIAL_PROGRESS = "Social Progress"
L.SORT_BY_PROGRESS_CHECKBOX = "Sort By Progress"
L.SORT_BY_PROGRESS_CHECKBOX_TOOLTIP = "Enable this option if you want the 'Sort' operation (" .. SHIFT_KEY_TEXT .. " Right Click) to sort by the total progress of each group (instead of by Name)"
L.SOULBINDCONDUITS_CHECKBOX = "|T" .. _.asset("Expansion_SL") .. ":0|t Conduits"
